def solve(inp):
    h,w=len(inp),len(inp[0]); bg=inp[0][0]
    cells=[(r,c) for r in range(h) for c in range(w) if inp[r][c]!=bg]
    def components(cells):
        seen=set(); out=[]
        for p in cells:
            if p in seen: continue
            stack=[p]; comp=[]
            while stack:
                a=stack.pop()
                if a in seen: continue
                seen.add(a); comp.append(a)
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nb=(a[0]+dr,a[1]+dc)
                        if nb in cells and nb not in seen: stack.append(nb)
            if len(comp)>1: out.append(comp)
        return out
    comps=components(cells)
    big=max(comps,key=lambda X:len(X))
    rs=[r for r,_ in big]; cs=[c for _,c in big]
    brr,bcc,bbr,bbc=min(rs),min(cs),max(rs),max(cs)
    P={(r-brr,c-bcc):inp[r][c] for r in range(brr,bbr+1) for c in range(bcc,bbc+1) if inp[r][c]!=bg}
    # marker color = most common non-bg color not in pattern
    from collections import Counter
    colors=Counter(inp[r][c] for r in range(h) for c in range(w) if inp[r][c]!=bg)
    patcols={v for v,_ in [( (r-brr,c-bcc),inp[r][c]) for r in range(brr,bbr+1) for c in range(bcc,bbc+1) if inp[r][c]!=bg]}
    mc=[k for k,v in colors.items() if k not in patcols][0]
    cr=(brr+bbr)//2; cc=(bcc+bbc)//2
    res=[row[:] for row in inp]
    for r,c in [(r,c) for r in range(h) for c in range(w) if inp[r][c]==mc]:
        for (i,j),v in P.items():
            rr,rc=r+i-cr,c+j-cc
            if 0<=rr<h and 0<=rc<w: res[rr][rc]=v
    return res

