    P=[[inp[brr+i][bcc+j] for j in range(bcc,bbc+1)] for i in range(brr,bbr+1)]
    ay=(hh-1)//2; ax=(ww-1)//2
    mk=[(r,c) for r in range(H) for c in range(W) if inp[r][c]!=bg and (r,c) not in set(best)]
